// Nombres reales de los locales, tal como los configuro cada cuenta (tabla "locales" de
// la base). Arrancan con estos valores por defecto (para no romper nada mientras carga),
// pero AppWrapper los actualiza apenas trae la lista real de locales al iniciar sesion.
// Como es un objeto mutable a nivel de modulo (no un estado de React), cualquier
// componente puede leerlo en el momento sin necesidad de que se lo pasen como prop.
let NOMBRES_LOCALES = { 1: "Local 1", 2: "Local 2" };
// Si el negocio tiene un solo local, no se muestra nada del segundo (selectores "Local 2",
// "Consolidado", "Todos", columnas de stock del otro local). Se recuerda en el navegador para
// que no aparezca y desaparezca al abrir; AppWrapper lo confirma con la lista real de locales.
let UN_SOLO_LOCAL = (() => { try { return localStorage.getItem("lumiere_un_local") === "1"; } catch (e) { return false; } })();
// Modo gastronomia (Mesas y Cocina en el menu): se lee del servidor al entrar
let GASTRO_ACTIVO = (() => { try { return localStorage.getItem("lumiere_gastro") === "1"; } catch (e) { return false; } })();
// Modulo Consultorio (Agenda, Pacientes, Recordatorios): suma su seccion y oculta lo que es de tienda
let CONSULTORIO_ACTIVO = (() => { try { return localStorage.getItem("lumiere_consultorio") === "1"; } catch (e) { return false; } })();
const OCULTAS_EN_CONSULTORIO = new Set(["etiquetas", "kits", "listas-precios", "traspasos", "control-inv", "ventas-online", "cambio-devolucion", "buscar-precio", "fidelizacion", "cupones", "giftcards", "portal"]);
const aplicarModulos = (m) => {
  GASTRO_ACTIVO = !!(m && m.gastronomia);
  CONSULTORIO_ACTIVO = !!(m && m.consultorio);
  try { localStorage.setItem("lumiere_gastro", GASTRO_ACTIVO ? "1" : "0"); localStorage.setItem("lumiere_consultorio", CONSULTORIO_ACTIVO ? "1" : "0"); } catch (e) {}
  window.dispatchEvent(new CustomEvent("lumiere-gastro"));
};
// Permisos de la persona que esta usando el sistema (los carga App al entrar). El jefe puede todo.
let PERMISOS_ACTUALES = [];
let ES_JEFE_ACTUAL = false;
// El estilo Girasoles (colores y collage) es solo del negocio original; los negocios clientes no lo ven
let ES_NEGOCIO_ORIGINAL = false;
const puedeHacer = (clave) => ES_JEFE_ACTUAL || PERMISOS_ACTUALES.includes(clave);
const nombreLocal = (id) => NOMBRES_LOCALES[Number(id)] || NOMBRES_LOCALES[1];
// Un color fuerte por local (para que en los pedidos se note a simple vista de que local es cada uno)
const COLORES_LOCAL_PED = ["#1f6fb2", "#8e3fb0", "#138a72", "#c0561b", "#b0336a"];
const colorLocalPed = (id) => COLORES_LOCAL_PED[((Number(id) || 1) - 1) % COLORES_LOCAL_PED.length];

