      if (t.paciente_id) API.get("/clientes").then(rc => { const c = (rc.data || []).find(x => x.id === t.paciente_id); if (c) { setClienteSeleccionado(c); setDniInput(c.cuit_dni || ""); cargarFicha(c.id, false); } }).catch(() => {});
